namespace TVOS; internal static class AppPaths { public static string Root=>Directory.Exists(@"C:\TV\web")?@"C:\TV":Find(); public static string Launcher=>Path.Combine(Root,"web","launcher","index.html"); public static string Remote=>Path.Combine(Root,"web","remote"); public static string Config=>Path.Combine(Root,"config"); public static string Services=>Path.Combine(Config,"services.json"); public static string Settings=>Path.Combine(Config,"settings.json"); public static string Cache=>Path.Combine(Root,"cache","artwork"); public static string WebView=>Path.Combine(Root,"cache","webview"); static string Find(){var d=new DirectoryInfo(AppContext.BaseDirectory);while(d!=null){if(Directory.Exists(Path.Combine(d.FullName,"web"))&&Directory.Exists(Path.Combine(d.FullName,"config")))return d.FullName;d=d.Parent;}return AppContext.BaseDirectory;} }